const original = $('Get Recently Measured Steps').item.json;
const signal = $input.item.json;
const LOW_TOUCH = ['email','content_download','landing_page','ads','webinar','linkedin_engage'];
const campaignId = original.campaign_id;
const stepId = original.step_id;
const salesforceCampaignId = original.salesforce_campaign_id || null;
const esc = (s) => String(s).replace(/'/g, "''");
let decision = 'reviewed';
let reason = 'No adaptive action needed.';
let sql = '';
let completionReason = null;
if (original.result === 'met') {
  decision = 'stopped';
  completionReason = 'goal_met';
  reason = 'Campaign goal met on step ' + original.step_number + ' (' + original.step_action_type + ') — remaining cadence steps cancelled.';
  sql = "update cadence_steps set adaptive_action='stopped', adaptive_reason='" + esc(reason) + "' where id=" + stepId + ";\n" +
        "update cadence_steps set status='cancelled' where campaign_id=" + campaignId + " and status in ('pending','recommended') and id<>" + stepId + ";\n" +
        "update campaigns set status='completed', completion_reason='" + esc(completionReason) + "' where id=" + campaignId + ";";
} else if (Number(signal.total_engagement) === 0 && signal.next_step_id) {
  decision = 'paused';
  reason = 'No engagement detected after step ' + original.step_number + ' (' + original.step_action_type + ') — next step pushed out 7 days.';
  sql = "update cadence_steps set adaptive_action='paused', adaptive_reason='" + esc(reason) + "' where id=" + stepId + ";\n" +
        "update cadence_steps set scheduled_for = scheduled_for + interval '7 days' where id=" + signal.next_step_id + ";";
} else if (Number(signal.total_engagement) > 0 && signal.next_step_id && LOW_TOUCH.includes(signal.next_step_action_type)) {
  const target = Number(signal.high_touch_used) === 0 ? 'linkedin_connect' : 'phone';
  decision = 'escalated';
  reason = 'Engagement seen but no conversion after step ' + original.step_number + ' (' + original.step_action_type + ') — next step escalated from ' + signal.next_step_action_type + ' to ' + target + '.';
  sql = "update cadence_steps set adaptive_action='escalated', adaptive_reason='" + esc(reason) + "' where id=" + stepId + ";\n" +
        "update cadence_steps set action_type='" + target + "' where id=" + signal.next_step_id + ";";
} else {
  sql = "update cadence_steps set adaptive_action='reviewed', adaptive_reason='" + esc(reason) + "' where id=" + stepId + ";";
}
// Item 3 fix: Salesforce Campaign Status write-back. Only a 'stopped' decision changes the
// campaign's own lifecycle (campaigns.status -> 'completed'); 'paused'/'escalated'/'reviewed'
// only touch individual cadence_steps and the campaign stays 'active' (Salesforce stays
// 'In Progress', no write needed). Auto-map: goal_met -> Completed, any other stop/terminal
// reason -> Aborted.
const salesforce_status = decision === 'stopped'
  ? (completionReason === 'goal_met' ? 'Completed' : 'Aborted')
  : null;
return [{ json: { decision: decision, sql: sql, step_id: stepId, campaign_id: campaignId, reason: reason, salesforce_campaign_id: salesforceCampaignId, salesforce_status: salesforce_status } }];
